```
class PasswordGenerator {
  constructor() {}

  generatePassword(length) {
    const characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()";
    let password = "";

    for (let i = 0; i < length; i++) {
      password += characters.charAt(Math.floor(Math.random() * characters.length));
    }

    return password;
  }

  generateStrongPassword() {
    const length = 12; // longitud de la contraseña por defecto
    const characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()abcdefghijklmnopqrstuvwxyz";
    let password = "";

    for (let i = 0; i < length; i++) {
      const char = characters.charAt(Math.floor(Math.random() * characters.length));
      if (i % 2 === 0) {
        password += char.toUpperCase();
      } else {
        password += char.toLowerCase();
      }
    }

    return password;
  }

  validatePassword(password) {
    const requirements = [
      /[a-z]/, // lowercase letter
      /[A-Z]/, // uppercase letter
      /[0-9]/, // number
      /[!@#$%^&*()]/ // special character
    ];

    for (const requirement of requirements) {
      if (!requirement.test(password)) {
        return false;
      }
    }

    return true;
  }
}

