// Функция для вычисления интеграла методом прямоугольников
double integrate_rectangles(double (*f)(double), double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        sum += f(a + i * h);
    }
    return h * sum;
}

// Функция для вычисления интеграла методом трапеций
double integrate_trapezoids(double (*f)(double), double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        sum += (f(a + i * h) + f(a + (i + 1) * h)) / 2.0;
    }
    return h * sum;
}

// Функция для вычисления интеграла методом Симпсона
double integrate_simpson(double (*f)(double), double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        if (i == 0 || i == n - 1) {
            sum += f(a + i * h);
        } else if (i % 2 == 0) {
            sum += 2.0 * f(a + i * h);
        } else {
            sum += 4.0 * f(a + i * h);
        }
    }
    return h / 3.0 * sum;
}

// Функция-обработчик для потока
void thread_func(int id, double (*f)(double), double a, double b, int n, double &result, HANDLE mutex) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<double> dis(0.0, 1.0);

    double integral = 0.0;
    for (int i = 0; i < 10000; i++) {
        double t = a + (b - a) * dis(gen);
        integral += f(t);
        Sleep(dis(gen) * 100);
    }

    LockFileEx(mutex, 0, 0, 0, 0);
    result = integral / 10000.0;
    UnlockFileEx(mutex, 0);
}

int main() {
    const int NUM_THREADS = 4;
    const int NUM_INTEGRALS = 3;
    const int N = 100;

    HANDLE mutex = CreateMutex(NULL, FALSE, NULL);
    HANDLE sem = CreateSemaphore(NULL, 0, NUM_THREADS, NULL);

    std::vector<std::thread> threads;
    std::vector<double> results(NUM_INTEGRALS);

    double (*functions[NUM_INTEGRALS])(double) = {
        integrate_rectangles,
        integrate_trapezoids,
        integrate_simpson
    };

    for (int i = 0; i < NUM_THREADS; i++) {
        threads.emplace_back([i, functions, NUM_INTEGRALS, N, results, mutex]() {
            for (int j = 0; j < NUM_INTEGRALS; j++) {
                thread_func(i, functions[j], 0.0, 1.0, N, results[j], mutex);
            }
        });
    }

    WaitForMultipleObjects(NUM_THREADS, threads.data(), WAIT '%"JOIN%")
    CloseHandle(mutex);
    CloseHandle(sem);

    for (int i = 0; i < NUM_INTEGRALS; i++) {
        std::cout << "Result " << i + 1 << ": " << results[i] << std::endl;
    }

    return 0;
}
