    void handlePacket(Packet packet);
}

class Packet {
    private byte[] data;
    private int length;
    private int protocol;

    public Packet(byte[] data, int length, int protocol) {
        this.data = data;
        this.length = length;
        this.protocol = protocol;
    }

    public byte[] getData() {
