// Definición de la estructura de nodo del árbol binario
struct Node {
    int value;
    Node* left;
    Node* right;
};

// Función para insertar un nuevo nodo en el árbol
Node* insertNode(Node* root, int value) {
    if (root == nullptr) {
        root = new Node();
        root->value = value;
        root->left = nullptr;
        root->right = nullptr;
    } else if (value < root->value) {
        root->left = insertNode(root->left, value);
    } else if (value > root->value) {
        root->right = insertNode(root->right, value);
    }
    return root;
}

// Función para buscar un valor en el árbol
Node* searchNode(Node* root, int value) {
    if (root == nullptr || root->value == value) {
        return root;
    } else if (value < root->value) {
        return searchNode(root->left, value);
    } else {
        return searchNode(root->right, value);
    }
}

int main() {
    Node* root = nullptr;

    // Insertar nodded en el árbol
    root = insertNode(root, 5);
    root = insertNode(root, 2);
    root = insertNode(root, 8);
    root = insertNode(root, 3);
    root = insertNode(root, 9);

    // Buscar un valor en el árbol
    Node* node = searchNode(root, 8);

    if (node != nullptr) {
        std::cout << "Valor encontrado: " << node->value << std::endl;
    } else {
        std::cout << "Valor no encontrado" << std::endl;
    }

    return 0;
}
```
La función `insertNode` inserta un nuevo nodo en el árbol con el valor proporcionado, y la función `searchNode` busca un valor en el árbol.

La función `searchNode` funciona de la siguiente manera:

* Si el árbol está vacío (es decir, si `root` es `nullptr`), entonces el valor no se encuentra en el árbol.
* Si el valor buscado es igual al valor del nodo actual, entonces el nodo se encuentra en el árbol y se devuelve.
* Si el valor buscado es menor que el valor del nodo actual, entonces se busca en el subárbol izquierdo.
* Si el valor buscado es mayor que el valor del nodo actual, entonces se busca en el subárbol derecho.

