import heapq

class Node:
    def __init__(self, name):
        self.name = name
        self.neighbors = {}

    def add_neighbor(self, node, length):
        self.neighbors[node] = length

def shortest_path_length(line_length, start, destination):
    known_points = set()
    unknown_points = [(0, start)]
    distance = {start: 0}

    while unknown_points:
        current_distance, current_node = heapq.heappop(unknown_points)

        if current_node == destination:
            return current_distance

        if current_node in known_points:
            continue

        known_points.add(current_node)

        for neighbor, length in current_node.neighbors.items():
            new_distance = current_distance + line_length[(current_node.name, neighbor)]
            if neighbor not in distance or new_distance < distance[neighbor]:
                distance[neighbor] = new_distance
                heapq.heappush(unknown_points, (new_distance, neighbor))

    return None

