```javascript
import { googleOAuthConfig } from './googleOAuthConfig';
import React, { Component } from 'react';
import { Paper, Typography } from '@material-ui/core';

class SessionManager extends Component {
  constructor(props) {
    super(props);
    this.state = {
      isAuthenticated: false,
      user: null
    };
  }

  async authenticate() {
    try {
      const response = await fetch(`https://accounts.google.com/o/oauth2/v2/auth?` +
        `client_id=${googleOAuthConfig.clientId}&` +
        `response_type=code&` +
        `redirect_uri=${googleOAuthConfig.redirectUri}&` +
        `scope=${googleOAuthConfig.scope}&` +
        `state=abc123`);
      const code = await response.json();
      const tokenResponse = await fetch('https://oauth2.googleapis.com/token', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded'
        },
        body: `grant_type=authorization_code&` +
          `code=${code}&` +
          `redirect_uri=${googleOAuthConfig.redirectUri}&` +
          `client_id=${googleOAuthConfig.clientId}&` +
          `client_secret=${googleOAuthConfig.clientSecret}`
      });
      const token = await tokenResponse.json();
      const decodedToken = await fetch('https://openidconnect.googleapis.com/v1/userinfo', {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${token.access_token}`
        }
      });
      const user = await decodedToken.json();
      this.setState({ isAuthenticated: true, user });
    } catch (error) {
      console.error(error);
    }
  }

  render() {
    return (
      <Paper style={{ padding: 20 }}>
        <Typography>{this.state.isAuthenticated ? `Welcome, ${this.state.user.name}!` : 'Vous devez vous authentifier'}</Typography>
        {this.state.isAuthenticated ? (
          <button onClick={() => this.authenticate()}>Deconnecter</button>
        ) : (
          <button onClick={() => this.authenticate()}>Se connecter avec Google</button>
        )}
      </Paper>
    );
  }
}

export default SessionManager;
```
This class manages the session state and handles the authentication flow using Google OAuth.

